ick)=\"onPageChange(currentPage - 1)\" [disabled]=\"currentPage === 1\" aria-label=\"Pagina precedente\">\r\n                    <i class=\"fas fa-angle-left\"></i>\r\n                  </button>\r\n                </li>\r\n                @for (p of pages; track p) {\r\n                  <li class=\"page-item\" [class.active]=\"p === currentPage\">\r\n                    <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(p)\">{{ p }}</button>\r\n                  </li>\r\n                }\r\n                <li class=\"page-item\" [class.disabled]=\"currentPage === totalPages\">\r\n                  <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(currentPage + 1)\" [disabled]=\"currentPage === totalPages\" aria-label=\"Pagina successiva\">\r\n                    <i class=\"fas fa-angle-right\"></i>\r\n                  </button>\r\n                </li>\r\n                <li class=\"page-item\" [class.disabled]=\"currentPage === totalPages\">\r\n                  <button class=\"page-link\" type=\"button\" (click)=\"onPageChange(totalPages)\" [disabled]=\"currentPage === totalPages\" aria-label=\"Ultima pagina\">\r\n                    <i class=\"fas fa-angle-double-right\"></i>\r\n                  </button>\r\n                </li>\r\n              </ul>\r\n            }\r\n          </div>\r\n        </nav>\r\n      }\r\n    </div>\r\n  </div>\r\n</div>\r\n",
